kit.score(function (S, T) {
  S.tempo(60, { t0: 0 });
  S.program('pad', 'pad', { rev: 0.7, bright: 0.3 }); S.program('bass', 'bass', { gain: -4 }); S.program('pl', 'pluck', { rev: 0.5 });
  // quiet bed under the voice, one chord per section
  const bed = (a, b, notes, root, v) => { S.chord('pad', notes, { t: a, dur: b - a, vel: v }); S.note('bass', root, { t: a, dur: b - a, vel: v + 14 }); };
  bed(0, T.crimes, ['D3', 'A3', 'F4'], 'D2', 22);
  bed(T.crimes, T.bound, ['A#2', 'F3', 'D4'], 'A#1', 24);
  bed(T.bound, T.crowd, ['G2', 'D3', 'A#3'], 'G1', 26);
  bed(T.crowd, T.END, ['D2', 'A2', 'D#3'], 'D1', 30);
  // one sound per event (DIRECTING.md §7)
  S.fx('pop', T.ledger + 1.9, { vel: 40 });
  S.fx('whoosh', T.ledger + 2.92, { dur: 0.3, vel: 34 });
  S.fx('pop', T.ledger + 3.42, { vel: 52 });
  S.fx('whoosh', T.bisect + 1.05, { dur: 0.7, vel: 30, into: 1 });
  S.fx('pop', T.bisect + 1.5, { vel: 40 });
  S.fx('pop', T.react + 0.24, { vel: 46 });
  S.note('pl', 'E5', { t: T.react + 0.3, dur: 0.8, vel: 30 });
  [0.5, 0.9, 1.3].forEach((x, i) => S.fx('pop', T.crimes + x, { vel: 38 + i * 6 }));
  S.fx('whoosh', T.crimes + 1.7, { dur: 0.38, vel: 44 });
  S.fx('thud', T.crimes + 2.08, { vel: 62 });
  S.fx('whoosh', T.bound + 0.84, { dur: 0.5, vel: 34 });
  S.fx('click', T.bound + 1.64, { vel: 44 });
  S.fx('whoosh', T.bound + 3.0, { dur: 0.95, vel: 30 });
  S.fx('pop', T.bound + 3.52, { vel: 36 });
  S.fx('thud', T.bound + 3.95, { vel: 54 });
  S.fx('thud', T.bound + 4.4, { vel: 30 });
  S.fx('pop', T.saw + 0.54, { vel: 38 });
  S.fx('whoosh', T.saw + 0.8, { dur: 0.38, vel: 40, into: 1 });
  S.fx('ding', T.saw + 1.18, { vel: 46, pitch: -7 });
  S.fx('thud', T.saw + 1.95, { vel: 34 }); S.fx('thud', T.saw + 2.13, { vel: 34 });
  for (let i = 0; i < 7; i++) S.fx('whoosh', T.crowd + 0.98 + i * 0.42, { dur: 0.3, vel: Math.max(10, 28 - i * 2), pitch: -8 });
  S.note('pl', 'D4', { t: T.close + 0.2, dur: 1.2, vel: 30 });
  S.master({ gain: -8, fadeOut: 1.0 });
});
